S = {1, 2, 4, 8, 15}
edges = []
for u in range(16):
    for v in range(u+1, 16):
        if (u ^ v) in S:
            edges.append((u, v))
print(len(edges), edges)

# verify triangle-free
adj = {i: set() for i in range(16)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
for u in range(16):
    for v in adj[u]:
        for w in adj[v]:
            if w != u and w in adj[u]:
                print("triangle", u,v,w)

# verify maximal: every non-edge has a common neighbor (adding it would create triangle)
ok = True
for u in range(16):
    for v in range(u+1, 16):
        if v not in adj[u]:
            if not (adj[u] & adj[v]):
                print("not maximal", u, v); ok=False
print("maximal:", ok)
